//! Momentum icons and the Webex client icons, drawn as tinted textures.
use eframe::egui::{self, Color32, Rect, Sense, TextureHandle, Vec2};
use std::collections::HashMap;

// ICON_TABLE (4,336 Momentum icons) and EMOJI_TABLE (3,033 emoji), sorted by name; generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/asset_tables.rs"));

fn find(table: &'static [(&'static str, &'static [u8])], name: &str) -> Option<&'static [u8]> {
    table.binary_search_by(|e| e.0.cmp(name)).ok().map(|i| table[i].1)
}

/// Webex client icons that Webox uses (kept locally in `assets/cisco/icons`, docs/cisco-assets.md) and the closest
/// Momentum icon (MIT, always embedded) drawn when a build does not have them.
pub(crate) const FALLBACKS: &[(&str, &str)] = &[
    ("Callhistory_empty_space", "call-192-cobalt-lime"),
    ("Contacts_empty_space", "contacts-320"),
    ("cisco-ai-assistant-color-gradient", "color-sparkle-regular"),
    ("emojipicker_illustration", "desert-open-results-192-cobalt-lime"),
    ("empty_voicemail", "call-voicemail-192-cobalt-lime"),
    ("highlights_avatar_120", "color-sparkle-filled"),
    ("lighthouse-filter-192-cobalt-lime", "flashlight-search-192-cobalt-lime"),
    ("message-send-320-cobalt-lime", "message-send-320"),
    ("update_24", "refresh-regular"), // the rail's update button
];

/// Whether an SVG is single-colour black line art (every fill / stroke / stop colour black or none).
fn mono_black(data: &[u8]) -> bool {
    let s = String::from_utf8_lossy(data);
    let mut any = false;
    for key in ["fill=\"", "stroke=\"", "stop-color=\""] {
        for part in s.split(key).skip(1) {
            let v = part.split('"').next().unwrap_or("").to_ascii_lowercase();
            match v.as_str() {
                "none" | "currentcolor" => {}
                "black" | "#000" | "#000000" => any = true,
                _ => return false,
            }
        }
    }
    any
}

static ART_INK: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0xF7F7F7FF);
/// The colour single-colour line art is drawn in: the active theme's primary text colour (set by `App::apply_theme`).
pub fn set_art_ink(c: Color32) { ART_INK.store(u32::from_be_bytes(c.to_array()), std::sync::atomic::Ordering::Relaxed) }
fn art_ink() -> Color32 { let [r, g, b, a] = ART_INK.load(std::sync::atomic::Ordering::Relaxed).to_be_bytes(); Color32::from_rgba_premultiplied(r, g, b, a) }

/// An icon by name: the Webex client icon when the build has it, else its Momentum fallback.
/// The embedded icon's own name for `name` (icons are drawn by `&'static str`; a name from a plugin is a `String`).
pub fn static_name(name: &str) -> Option<&'static str> {
    ICON_TABLE.binary_search_by(|e| e.0.cmp(name)).ok().map(|i| ICON_TABLE[i].0)
}

fn lookup(name: &str) -> Option<&'static [u8]> {
    find(ICON_TABLE, name).or_else(|| FALLBACKS.iter().find(|f| f.0 == name).and_then(|f| find(ICON_TABLE, f.1)))
}

/// The emoji file name for a character sequence: lowercase code points joined by "-".
pub fn emoji_file(s: &str) -> String { s.chars().map(|c| format!("{:x}", c as u32)).collect::<Vec<_>>().join("-") }

fn raster(data: &[u8], tint: bool) -> Option<egui::ColorImage> { raster_px(data, tint, PX, None) }
/// An icon by name (the name tells the glyph grid of pixel-grid glyphs, see glyph_with_view_box).
fn raster_icon(name: &str, data: &[u8]) -> Option<egui::ColorImage> { raster_px(data, true, PX, Some(name)) }

/// Icon-font glyphs (`<svg id=..><path unicode=.. [transform=..] d=..>`, no width / height / viewBox: an icon font
/// exported glyph by glyph) get the viewBox of their em box, so they render at their size and baseline:
/// - font units (`transform="scale(1,-1)"`): a 1024-unit em with ascent 960 and descent 64, so `0 -960 1024 1024`
///   (a few glyphs reach beyond the em box and keep their whole outline);
/// - pixel-grid glyphs (no flip, coordinates in px, e.g. apps_16 1..15, adjust_12 0..12): `0 0 N N` with N the
///   size in the file name (`_12`, `_16` ...), or - without one / when the outline is larger - the smallest icon grid
///   (12, 16, 20, 24, 28, 32, 40, 48, 64) that holds it.
///
/// Returns the patched SVG, or None when the file isn't such a glyph (has its own size) or can't be parsed.
fn glyph_with_view_box(data: &[u8], name: Option<&str>) -> Option<Vec<u8>> {
    let s = std::str::from_utf8(data).ok()?;
    let open = s.find("<svg")?;
    let tag_end = open + s[open..].find('>')?;
    let tag = &s[open..tag_end];
    if !s.contains("unicode=") || tag.contains("viewBox") || tag.contains("width=") { return None; }
    let font_units = s.contains("scale(1,-1)") || s.contains("scale(1, -1)");
    let tree = resvg::usvg::Tree::from_data(data, &resvg::usvg::Options::default()).ok()?;
    let b = tree.root().abs_bounding_box();
    let vb = if font_units {
        let (top, bottom) = (b.top().floor().min(-960.0), b.bottom().ceil().max(64.0));
        let w = b.right().ceil().max(1024.0);
        format!("0 {top} {w} {}", bottom - top)
    } else {
        let ext = b.right().max(b.bottom());
        let named = name.and_then(grid_from_name).filter(|n| *n as f32 + 0.5 >= ext);
        let n = named.or_else(|| [12, 16, 20, 24, 28, 32, 40, 48, 64].into_iter().find(|n| ext <= *n as f32 + 0.5)).unwrap_or(ext.ceil() as u32);
        format!("0 0 {n} {n}")
    };
    let mut out = String::with_capacity(s.len() + 32);
    out.push_str(&s[..tag_end]);
    out.push_str(&format!(" viewBox=\"{vb}\""));
    out.push_str(&s[tag_end..]);
    Some(out.into_bytes())
}

/// The icon grid in a file name: "arrow-down_12" -> 12, "settings_12_w" -> 12, "server-connection" -> None.
fn grid_from_name(name: &str) -> Option<u32> {
    name.split('_').skip(1).find_map(|p| p.parse::<u32>().ok()).filter(|n| (6..=64).contains(n))
}

/// Transparent texels around every raster. egui draws a texture as a quad without edge anti-aliasing, so artwork that reaches
/// the edge of its view box (a full disc, a round badge) was cut flat where it touched the quad's border; with this margin
/// the content never touches it. Draw the texture into `grow(rect, px)`, which keeps the content at `rect`'s size.
const PAD: u32 = 2;

/// The rect to draw a `raster_px` texture with content size `px` into, so its content fills `rect` exactly.
fn grow(rect: Rect, px: u32) -> Rect { rect.expand(rect.width() * PAD as f32 / px.max(1) as f32) }

/// Rasterises the SVG with its content `px_size` px wide, plus `PAD` transparent texels on every side.
fn raster_px(data: &[u8], tint: bool, px_size: u32, name: Option<&str>) -> Option<egui::ColorImage> {
    let patched = glyph_with_view_box(data, name);
    let data = patched.as_deref().unwrap_or(data);
    let tree = resvg::usvg::Tree::from_data(data, &resvg::usvg::Options::default()).ok()?;
    let side = px_size + 2 * PAD;
    let mut pix = resvg::tiny_skia::Pixmap::new(side, side)?;
    let s = px_size as f32 / tree.size().width().max(tree.size().height());
    resvg::render(&tree, resvg::tiny_skia::Transform::from_scale(s, s).post_translate(PAD as f32, PAD as f32), &mut pix.as_mut());
    // Icons: white with the icon's coverage as alpha, so any tint can be applied. Emoji keep their colours.
    let px: Vec<Color32> = pix.pixels().iter().map(|p| if tint { Color32::from_white_alpha(p.alpha()) }
        else { Color32::from_rgba_premultiplied(p.red(), p.green(), p.blue(), p.alpha()) }).collect();
    Some(egui::ColorImage { size: [side as usize, side as usize], pixels: px })
}
pub const LOGO_256: &[u8] = include_bytes!("../../assets/logo-256.png");

// The application icon (window / taskbar / tray) at sizes 16, 20, 24, 32, 40, 48, 60, 64, 256, so every size is the
// artwork's own and nothing is scaled blurry.
pub const APP_ICON_256: &[u8] = include_bytes!("../../assets/icon/webox-256.png");
/// The smallest embedded frame that is at least `size` px (the 256 px frame for anything larger).
pub fn app_icon_frame(size: u32) -> &'static [u8] {
    match size {
        0..=16 => include_bytes!("../../assets/icon/webox-16.png"),
        17..=20 => include_bytes!("../../assets/icon/webox-20.png"),
        21..=24 => include_bytes!("../../assets/icon/webox-24.png"),
        25..=32 => include_bytes!("../../assets/icon/webox-32.png"),
        33..=40 => include_bytes!("../../assets/icon/webox-40.png"),
        41..=48 => include_bytes!("../../assets/icon/webox-48.png"),
        49..=60 => include_bytes!("../../assets/icon/webox-60.png"),
        61..=64 => include_bytes!("../../assets/icon/webox-64.png"),
        _ => APP_ICON_256,
    }
}
