#[derive(Clone, Copy, PartialEq, Eq, Hash)]
enum Kind { Icon, Art, Emoji }
static PREWARMED: std::sync::Mutex<Option<HashMap<(Kind, &'static str), egui::ColorImage>>> = std::sync::Mutex::new(None);

/// Starts rasterising the prewarm list on a worker thread (call once, before the window opens).
pub fn prewarm() {
    let _ = std::thread::Builder::new().name("icon-prewarm".into()).spawn(|| {
        let lists: [(Kind, &[&'static str]); 3] = [(Kind::Icon, PREWARM_ICONS), (Kind::Art, PREWARM_ART), (Kind::Emoji, PREWARM_EMOJI)];
        for (kind, names) in lists {
            for &name in names {
                let img = match kind {
                    Kind::Icon => lookup(name).and_then(|d| raster_icon(name, d)),
                    Kind::Art => lookup(name).and_then(|d| raster_px(d, false, 256, None)),
                    Kind::Emoji => find(EMOJI_TABLE, name).and_then(|d| raster(d, false)),
                };
                let Some(img) = img else { continue };
                if let Ok(mut m) = PREWARMED.lock() { m.get_or_insert_with(HashMap::new).insert((kind, name), img); }
            }
        }
    });
}
fn take_prewarmed(kind: Kind, name: &'static str) -> Option<egui::ColorImage> {
    PREWARMED.lock().ok()?.as_mut()?.remove(&(kind, name))
}

/// Icons, emoji and illustrations are rasterised once (64 / 256 px) and drawn much smaller: with mipmaps the GPU scales them down
/// smoothly. Plain linear filtering sampled only a few texels per pixel, so round edges turned to steps and small details (an
/// emoji's mouth) vanished.
const SCALED: egui::TextureOptions = egui::TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..egui::TextureOptions::LINEAR };

#[derive(Default)]
pub struct Icons(HashMap<&'static str, TextureHandle>, HashMap<(&'static str, u32), (TextureHandle, bool)>, HashMap<(&'static str, u32), TextureHandle>);

impl Icons {
    fn tex(&mut self, ctx: &egui::Context, name: &'static str) -> Option<egui::TextureId> {
        if let Some(t) = self.0.get(name) { return Some(t.id()); }
        let img = match take_prewarmed(Kind::Icon, name) { Some(i) => i, None => raster_icon(name, lookup(name)?)? };
        let t = ctx.load_texture(name, img, SCALED);
        let id = t.id();
        self.0.insert(name, t);
        Some(id)
    }

    /// Draws a multi-colour illustration / avatar (an SVG from the icon set) in its own colours, rasterised at 256 px.
    pub fn art(&mut self, ui: &egui::Ui, name: &'static str, rect: Rect) -> bool {
        let Some(data) = lookup(name) else { return false };
        // Single-colour black line art (the Momentum fallbacks contacts-320 / message-send-320, ...) is drawn in the theme's ink,
        // like the -black / -white art variants switch by theme. Found once with the raster (kept with it), not every frame.
        // Rasterised at the drawn size in device pixels (cached per size), snapped to the pixel grid, like `paint`: a 256 px raster
        // shrunk with mipmaps also shrank the transparent margin below a pixel, so a full disc touched the quad's border again
        // and was cut flat on whichever sides the sub-pixel position put on that border.
        let ppp = ui.ctx().pixels_per_point();
        let px = (rect.width() * ppp).round().clamp(1.0, 1024.0) as u32;
        if !self.1.contains_key(&(name, px)) {
            let mono = mono_black(data);
            let Some(img) = raster_px(data, mono, px, None) else { return false };
            self.1.insert((name, px), (ui.ctx().load_texture(format!("art-{name}@{px}"), img, egui::TextureOptions::LINEAR), mono));
        }
        let (tex, mono) = &self.1[&(name, px)];
        let tint = if *mono { art_ink() } else { Color32::WHITE };
        ui.painter().image(tex.id(), grow(on_grid(rect, px, ppp), px), Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), tint);
        true
    }

    /// Draws a colour emoji; false when there is no picture for that character.
    pub fn emoji(&mut self, ui: &egui::Ui, s: &str, rect: Rect) -> bool {
        let Some(key) = emoji_key(s) else { return false }; // e.g. ❤ is stored as 2764-fe0f
        // Rasterised at the drawn size, like `paint`: a small emoji keeps its details (a 64 px raster scaled down lost the mouth).
        let px = (rect.width() * ui.ctx().pixels_per_point()).round().clamp(1.0, 256.0) as u32;
        if !self.2.contains_key(&(key, px)) {
            let Some(data) = find(EMOJI_TABLE, key) else { return false };
            let Some(img) = raster_px(data, false, px, None) else { return false };
            self.2.insert((key, px), ui.ctx().load_texture(format!("{key}@{px}"), img, egui::TextureOptions::LINEAR));
        }
        ui.painter().image(self.2[&(key, px)].id(), grow(on_grid(rect, px, ui.ctx().pixels_per_point()), px), Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), Color32::WHITE);
        true
    }

    /// Webox's own logo (assets/logo-256.png), drawn in its own colours.
    pub fn logo(&mut self, ui: &egui::Ui, rect: Rect) {
        if !self.0.contains_key("logo") {
            let Ok(img) = image::load_from_memory(LOGO_256) else { return };
            let img = img.to_rgba8();
            let ci = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
            self.0.insert("logo", ui.ctx().load_texture("logo", ci, SCALED)); // 256 px drawn at 15 pt: mipmapped, or its round edge steps
        }
        let id = self.0["logo"].id();
        ui.painter().image(id, rect, Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), Color32::WHITE);
    }

    /// Loads (once) and returns a raw PNG/JPEG as a texture id plus its pixel size, cached by `key`.
    pub fn png(&mut self, ui: &egui::Ui, key: &'static str, bytes: &[u8]) -> Option<(egui::TextureId, [usize; 2])> {
        if !self.0.contains_key(key) {
            let img = image::load_from_memory(bytes).ok()?.to_rgba8();
            let ci = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
            self.0.insert(key, ui.ctx().load_texture(key, ci, SCALED)); // usually drawn smaller than its pixels
        }
        let t = &self.0[key];
        Some((t.id(), t.size()))
    }

    /// Same as `paint` (kept for its callers; every icon is rasterised at its drawn size now).
    pub fn paint_exact(&mut self, ui: &egui::Ui, name: &'static str, rect: Rect, tint: Color32) { self.paint(ui, name, rect, tint) }

    /// Draws an icon rasterised at `rect`'s size in device pixels (cached per size), as sharp as the SVG allows: the 64 px raster
    /// scaled down turned round edges into steps. Falls back to that raster when the SVG can't be rasterised at this size.
    pub fn paint(&mut self, ui: &egui::Ui, name: &'static str, rect: Rect, tint: Color32) {
        let px = (rect.width() * ui.ctx().pixels_per_point()).round().clamp(1.0, 256.0) as u32;
        if !self.2.contains_key(&(name, px)) {
            let Some(img) = lookup(name).and_then(|d| raster_px(d, true, px, Some(name))) else {
                if let Some(id) = self.tex(ui.ctx(), name) { ui.painter().image(id, grow(rect, PX), Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), tint); }
                return;
            };
            self.2.insert((name, px), ui.ctx().load_texture(format!("{name}@{px}"), img, egui::TextureOptions::LINEAR));
        }
        ui.painter().image(self.2[&(name, px)].id(), grow(on_grid(rect, px, ui.ctx().pixels_per_point()), px), Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), tint);
    }

    /// An icon button: `size` is the clickable square, the icon is drawn at `icon` px inside it.
    pub fn button(&mut self, ui: &mut egui::Ui, name: &'static str, size: f32, icon: f32, tint: Color32, hover_bg: Color32) -> egui::Response {
        let (r, resp) = ui.allocate_exact_size(Vec2::splat(size), Sense::click());
        if resp.hovered() { ui.painter().circle_filled(r.center(), size / 2.0, hover_bg); }
        self.paint(ui, name, Rect::from_center_size(r.center(), Vec2::splat(icon)), tint);
        resp
    }
}

/// `rect` moved onto the device pixel grid with its side exactly `px` device pixels (same centre within half a pixel), so a
/// raster made at `px` is drawn 1:1; at a fractional position the GPU's bilinear filter smeared every edge over two pixels.
/// A rect that isn't square (the picture stretched on purpose) is left as it is.
fn on_grid(rect: Rect, px: u32, ppp: f32) -> Rect {
    if (rect.width() - rect.height()).abs() > 0.5 { return rect }
    let side = px as f32 / ppp;
    let min = rect.center() - egui::Vec2::splat(side / 2.0);
    Rect::from_min_size(egui::pos2((min.x * ppp).round() / ppp, (min.y * ppp).round() / ppp), egui::Vec2::splat(side))
}

/// True if the emoji set has a picture for this character sequence (same lookup as `Icons::emoji`).
pub fn emoji_exists(s: &str) -> bool { emoji_key(s).is_some() }

/// The name of the emoji file for a character sequence: an EXACT code-point match (with / without U+FE0F), never a fuzzy one.
/// Memoised per thread: the UI asks for every emoji it draws (messages, reactions, the picker's cells) each frame.
pub fn emoji_key(s: &str) -> Option<&'static str> {
    thread_local! {
        static KEYS: std::cell::RefCell<HashMap<String, Option<&'static str>>> = std::cell::RefCell::new(HashMap::new());
    }
    if let Some(k) = KEYS.with(|m| m.borrow().get(s).copied()) { return k; }
    let found = emoji_key_uncached(s);
    KEYS.with(|m| { let mut m = m.borrow_mut(); if m.len() >= 8192 { m.clear(); } m.insert(s.to_string(), found); });
    found
}

fn emoji_key_uncached(s: &str) -> Option<&'static str> {
    let file = emoji_file(s);
    let bare = file.replace("-fe0f", "");
    let with_vs = format!("{bare}-fe0f");
    let found = [file.as_str(), bare.as_str(), with_vs.as_str()].into_iter()
        .find_map(|f| EMOJI_TABLE.binary_search_by(|e| e.0.cmp(f)).ok().map(|i| EMOJI_TABLE[i].0));
    found
}

#[cfg(test)]
mod emoji_tests {
    use super::*;

    /// A build without the Webex client icons still draws every icon Webox uses: each one it may lack has a Momentum
    /// fallback that is always embedded.
    #[test]
    fn fallbacks_point_at_embedded_icons() {
        for (name, to) in FALLBACKS {
            assert!(find(ICON_TABLE, to).is_some(), "{name}: fallback {to} is not in assets/icons");
            assert!(lookup(name).is_some(), "{name}");
        }
    }

    /// No emoji file may really be an icon (e.g. 1f60b must be the emoji, not a calendar).
    #[test]
    fn emoji_files_are_not_icons() {
        let icons: std::collections::HashSet<&[u8]> = ICON_TABLE.iter().map(|e| e.1).collect();
        let bad: Vec<&str> = EMOJI_TABLE.iter().filter(|e| icons.contains(e.1)).map(|e| e.0).collect();
        assert!(bad.is_empty(), "emoji files identical to icons: {bad:?}");
        // Emoji pictures are the Twitter set: 36x36 colour artwork.
        let odd: Vec<&str> = EMOJI_TABLE.iter().filter(|e| !std::str::from_utf8(e.1).unwrap_or("").contains("viewBox=\"0 0 36 36\"")).map(|e| e.0).collect();
        assert!(odd.is_empty(), "emoji files that are not 36x36 artwork: {odd:?}");
    }

    /// Rows / columns of a rastered icon that have coverage: (first, last) of each.
    fn ink(img: &egui::ColorImage) -> Option<((usize, usize), (usize, usize))> {
        let [w, h] = img.size;
        let on = |x: usize, y: usize| img.pixels[y * w + x].a() > 40;
        let rows: Vec<usize> = (0..h).filter(|y| (0..w).any(|x| on(x, *y))).collect();
        let cols: Vec<usize> = (0..w).filter(|x| (0..h).any(|y| on(*x, y))).collect();
        let p = PAD as usize; // positions in the content, without the transparent margin
        Some(((*cols.first()? - p, *cols.last()? - p), (*rows.first()? - p, *rows.last()? - p)))
    }

    #[test]
    fn font_glyph_svgs_render_in_their_em_box() {
        // A font-unit glyph without any size: arrow-down_12 (in assets/icons, always embedded).
        let svg = find(ICON_TABLE, "arrow-down_12").expect("arrow-down_12");
        assert!(!std::str::from_utf8(svg).unwrap().contains("viewBox"));
        let img = raster_icon("arrow-down_12", svg).expect("rastered");
        let ((x0, x1), (y0, y1)) = ink(&img).expect("visible");
        // Outline x 80..939, y (flipped) -709..-192 of the em 0..1024 / -960..64: on 64 px about x 5..58, y 16..48.
        assert!((4..=6).contains(&x0) && (57..=59).contains(&x1), "x {x0}..{x1}");
        assert!((14..=17).contains(&y0) && (47..=49).contains(&y1), "y {y0}..{y1}");
        // A pixel-grid glyph: apps_16 (outline 1..15 on a 16 grid -> 4..60 of 64 px).
        if let Some(svg) = lookup("apps_16") {
            let ((x0, x1), (y0, y1)) = ink(&raster_icon("apps_16", svg).expect("apps_16")).expect("visible");
            assert!(x0 >= 3 && x0 <= 5 && x1 >= 58 && y0 >= 3 && y1 >= 58, "apps_16 {x0}..{x1} {y0}..{y1}");
        }
        // An ordinary icon is untouched.
        assert!(glyph_with_view_box(find(ICON_TABLE, "arrow-down-bold").unwrap(), Some("arrow-down-bold")).is_none());
        assert_eq!(grid_from_name("settings_12_w"), Some(12));
        assert_eq!(grid_from_name("server-connection"), None);
    }

    #[test]
    fn savoring_face_is_not_a_calendar() {
        // 1f60b is the Twemoji savoring face.
        assert_eq!(emoji_key("\u{1F60B}"), Some("1f60b"));
        assert_eq!(emoji_key("\u{1FAEB}"), None); // too new for the set: omitted, never an icon
        assert_eq!(emoji_key("\u{1F600}"), Some("1f600"));
    }
}
